create extension if not exists pgcrypto;
create extension if not exists ltree;
create table organisation(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,created_at timestamptz not null default now());
create table app_user(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,identity_subject text not null,email text not null,display_name text not null,unique(organisation_id,identity_subject),unique(organisation_id,email));
create table business_service(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,name text not null,owner_id uuid references app_user(id),criticality text not null check(criticality in('low','medium','high','critical')),unique(organisation_id,name));
create table configuration_item(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,service_id uuid references business_service(id),name text not null,ci_type text not null,external_key text,attributes jsonb not null default '{}'::jsonb,last_discovered_at timestamptz,unique(organisation_id,external_key));
create table ci_relationship(parent_id uuid not null references configuration_item(id) on delete cascade,child_id uuid not null references configuration_item(id) on delete cascade,relationship text not null,primary key(parent_id,child_id,relationship),check(parent_id<>child_id));
create table incident(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,number bigint generated always as identity,title text not null,description text not null default '',service_id uuid references business_service(id),ci_id uuid references configuration_item(id),impact text not null check(impact in('low','medium','high','critical')),urgency text not null check(urgency in('low','medium','high','critical')),priority text not null check(priority in('P1','P2','P3','P4')),state text not null default 'new' check(state in('new','assigned','in_progress','pending','resolved','closed')),assignee_id uuid references app_user(id),created_at timestamptz not null default now(),resolved_at timestamptz,unique(organisation_id,number));
create index incident_search_idx on incident using gin(to_tsvector('english',title||' '||description));
create table change_record(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,number bigint generated always as identity,title text not null,change_type text not null check(change_type in('standard','normal','emergency')),risk_score integer not null check(risk_score between 0 and 100),state text not null default 'draft',starts_at timestamptz,ends_at timestamptz,created_at timestamptz not null default now(),unique(organisation_id,number));
create table audit_event(id bigint generated always as identity primary key,organisation_id uuid not null references organisation(id) on delete cascade,actor_id text not null,action text not null,entity_type text not null,entity_id text not null,payload jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default now());
create table role_policy(organisation_id uuid not null references organisation(id) on delete cascade,role_key text not null,permissions text[] not null default '{}',updated_by text not null,updated_at timestamptz not null default now(),primary key(organisation_id,role_key));
